+codeunit 50105 "Bank Acc. Verify ARG"
+{
+  Access = Internal;
+
+  procedure VerifyBankAccount(pBankAccountNo: Code[20])
+  var
+    _BankAccount: Record "Bank Account";
+    _AccountBlockedErr: Label 'Bank account %1 is blocked.';
+  begin
+    _BankAccount.SetLoadFields(Blocked);
