+++ b/src/CustRatingMgtARG.Codeunit.al
@@ -0,0 +1,32 @@
+codeunit 50100 "Cust. Rating Mgt ARG"
+{
+  Access = Internal;
+
+  var
+    _RatingFactor: Decimal;
+
+  procedure CalculateRating(CustomerNo: Code[20]): Decimal
+  var
+    Customer: Record Customer;
+    ratingBase: Decimal;
+    _CustomerNotFoundErr: Label 'Table %1 does not contain %2 = %3.', Comment = '%1 = Table name, %2 = Field name, %3 = Value';
+  begin
+    Customer.SetLoadFields("Credit Limit (LCY)");
+    if not Customer.Get(CustomerNo) then
+      Error(_CustomerNotFoundErr, Customer.TableCaption(), Customer.FieldCaption("No."), CustomerNo);
+    ratingBase := Customer."Credit Limit (LCY)" / 1000;
+    exit(ratingBase * this.GetRatingFactor());
+  end;
+
+  procedure SetRatingFactor(pFactor: Decimal)
+  begin
+    _RatingFactor := pFactor;
+  end;
+
+  local procedure GetRatingFactor(): Decimal
+  begin
+    if _RatingFactor = 0 then
+      exit(1);
+    exit(_RatingFactor);
+  end;
+}
