+++ b/src/ItemPriceCheckARG.Codeunit.al
@@ -0,0 +1,18 @@
+codeunit 50101 "Item Price Check ARG"
+{
+  Access = Internal;
+
+  procedure GetDiscountedPrice(pItemNo: Code[20]) rUnitPrice: Decimal
+  var
+    _totalDiscount: Decimal;
+    _item: Record Item;
+    _PriceFactor: Decimal;
+  begin
+    _item.SetLoadFields("Unit Price");
+    if not _item.Get(pItemNo) then
+      exit(0);
+    _PriceFactor := 0.9;
+    _totalDiscount := _item."Unit Price" * (1 - _PriceFactor);
+    rUnitPrice := _item."Unit Price" - _totalDiscount;
+  end;
+}
