+++ b/src/ContactSyncARG.Codeunit.al
@@ -0,0 +1,34 @@
+codeunit 50115 "Contact Sync ARG"
+{
+  Access = Internal;
+
+  var
+    LastSyncDateTime: DateTime;
+
+  procedure SyncContact(pContactNo: Code[20]) rSynced: Boolean
+  var
+    _Contact: Record Contact;
+    _syncCount: Integer;
+  begin
+    _Contact.SetLoadFields(Name, "E-Mail");
+    if not _Contact.Get(pContactNo) then
+      exit(false);
+    _syncCount := this.PushContact(_Contact);
+    LastSyncDateTime := CurrentDateTime();
+    rSynced := _syncCount > 0;
+  end;
+
+  procedure GetLastSyncTime() rLastSync: DateTime
+  begin
+    rLastSync := LastSyncDateTime;
+  end;
+
+  local procedure PushContact(pContact: Record Contact): Integer
+  begin
+    if pContact.Name = '' then
+      exit(0);
+    if pContact."E-Mail" = '' then
+      exit(0);
+    exit(1);
+  end;
+}
