@@ -0,0 +1,18 @@
+codeunit 50116 "Item Margin Calc ARG"
+{
+  Access = Internal;
+
+  procedure GetMarginPct(pItemNo: Code[20]) rMarginPct: Decimal
+  var
+    _Item: Record Item;
+    _marginAmount: Decimal;
+  begin
+    _Item.SetLoadFields("Unit Price", "Unit Cost");
+    if not _Item.Get(pItemNo) then
+      exit(0);
+    if _Item."Unit Price" = 0 then
+      exit(0);
+    _marginAmount := _Item."Unit Price" - _Item."Unit Cost";
+    rMarginPct := Round(_marginAmount / _Item."Unit Price" * 100, 0.01);
+  end;
+}
