+codeunit 50113 "Release Audit ARG"
+{
+  Access = Internal;
+
+  [EventSubscriber(ObjectType::Codeunit, Codeunit::"Release Sales Document", 'OnAfterReleaseSalesDoc', '', false, false)]
+  local procedure OnAfterReleaseSalesDoc(var SalesHeader: Record "Sales Header"; PreviewMode: Boolean)
+  var
+    _ReleaseAuditLog: Record "Release Audit Log ARG";
+    _Customer: Record Customer;
+  begin
+    if PreviewMode then
+      exit;
+    _Customer.SetLoadFields(Name);
+    _Customer.Get(SalesHeader."Sell-to Customer No.");
+    _ReleaseAuditLog."Document No." := SalesHeader."No.";
+    _ReleaseAuditLog."Customer Name" := _Customer.Name;
+    _ReleaseAuditLog."Released At" := CurrentDateTime();
+    _ReleaseAuditLog.Insert();
+    Commit();
+  end;
+}
