+codeunit 50111 "Rating Apply ARG"
+{
+  Access = Internal;
+
+  procedure ApplyRatingFactor(pAmount: Decimal) rRated: Decimal
+  var
+    _RatingSetup: Record "Rating Setup ARG";
+  begin
+    if not _RatingSetup.Get() then
+      _RatingSetup.Init();
+    rRated := pAmount * _RatingSetup."Default Rating Factor";
+  end;
+
+  procedure RoundRating(pAmount: Decimal) rRounded: Decimal
+  var
+    _RatingSetup: Record "Rating Setup ARG";
+  begin
+    if not _RatingSetup.Get() then
+      _RatingSetup.Init();
+    rRounded := Round(pAmount, _RatingSetup."Rounding Precision");
+  end;
+
+  procedure SetDefaultFactor(pFactor: Decimal)
+  var
+    _RatingSetup: Record "Rating Setup ARG";
+  begin
+    if not _RatingSetup.Get() then begin
+      _RatingSetup.Init();
+      _RatingSetup.Insert();
+    end;
+    _RatingSetup.Validate("Default Rating Factor", pFactor);
+    _RatingSetup.Modify();
+  end;
+}
