new file mode 100644
--- /dev/null
+++ b/src/SalesArchiverARG.Codeunit.al
@@ -0,0 +1,51 @@
+codeunit 50126 "Sales Archiver ARG"
+{
+  Access = Internal;
+
+  procedure ArchiveOrder(pDocumentNo: Code[20]) rArchived: Boolean
+  var
+    _SalesHeader: Record "Sales Header";
+    _SalesHeaderArchive: Record "Sales Header Archive";
+  begin
+    if not _SalesHeader.Get(_SalesHeader."Document Type"::Order, pDocumentNo) then
+      exit(false);
+    _SalesHeaderArchive.Init();
+    _SalesHeaderArchive.TransferFields(_SalesHeader);
+    _SalesHeaderArchive."Doc. No. Occurrence" := 1;
+    _SalesHeaderArchive."Version No." := this.GetNextVersionNo(pDocumentNo);
+    rArchived := _SalesHeaderArchive.Insert();
+  end;
+
+  procedure BuildLineSummary(var pTemp_SalesLine: Record "Sales Line" temporary) rSummary: Text
+  var
+    _LineSummaryLbl: Label '%1 x %2', Comment = '%1 = Quantity, %2 = Description';
+  begin
+    if pTemp_SalesLine.FindSet() then
+      repeat
+        if rSummary <> '' then
+          rSummary += ', ';
+        rSummary += StrSubstNo(_LineSummaryLbl, pTemp_SalesLine.Quantity, pTemp_SalesLine.Description);
+      until pTemp_SalesLine.Next() = 0;
+  end;
+
+  procedure IsOrderArchivingEnabled() rEnabled: Boolean
+  var
+    _SalesReceivablesSetup: Record "Sales & Receivables Setup";
+  begin
+    if _SalesReceivablesSetup.Get() then
+      rEnabled := _SalesReceivablesSetup."Archive Orders";
+  end;
+
+  local procedure GetNextVersionNo(pDocumentNo: Code[20]) rVersionNo: Integer
+  var
+    _SalesHeaderArchive: Record "Sales Header Archive";
+  begin
+    _SalesHeaderArchive.SetRange("Document Type", _SalesHeaderArchive."Document Type"::Order);
+    _SalesHeaderArchive.SetRange("No.", pDocumentNo);
+    _SalesHeaderArchive.SetLoadFields("Version No.");
+    if _SalesHeaderArchive.FindLast() then
+      rVersionNo := _SalesHeaderArchive."Version No." + 1
+    else
+      rVersionNo := 1;
+  end;
+}
