+++ b/src/VendorRatingMgtARG.Codeunit.al
@@ -0,0 +1,32 @@
+codeunit 50117 "Vendor Rating Mgt ARG"
+{
+  Access = Internal;
+
+  var
+    RatingCache: Dictionary of [Code[20], Decimal];
+
+  procedure GetVendorRating(pVendorNo: Code[20]) rRating: Decimal
+  var
+    _Vendor: Record Vendor;
+  begin
+    if RatingCache.ContainsKey(pVendorNo) then
+      exit(RatingCache.Get(pVendorNo));
+    _Vendor.SetLoadFields(Blocked);
+    if not _Vendor.Get(pVendorNo) then
+      exit(0);
+    rRating := this.CalculateRating(_Vendor);
+    RatingCache.Add(pVendorNo, rRating);
+  end;
+
+  procedure ClearRatingCache()
+  begin
+    Clear(RatingCache);
+  end;
+
+  local procedure CalculateRating(pVendor: Record Vendor): Decimal
+  begin
+    if pVendor.Blocked <> pVendor.Blocked::" " then
+      exit(0);
+    exit(5);
+  end;
+}
