+++ b/src/ReceiptNotifyARG.Codeunit.al
@@ -0,0 +1,26 @@
+codeunit 50118 "Receipt Notify ARG"
+{
+  Access = Internal;
+
+  procedure BuildReceiptMessage(pReceiptNo: Code[20]) rMessage: Text
+  begin
+    if not this.IsReceiptPosted(pReceiptNo) then
+      exit('');
+    rMessage := this.FormatNotification(pReceiptNo);
+  end;
+
+  local procedure IsReceiptPosted(pReceiptNo: Code[20]): Boolean
+  var
+    _PurchRcptHeader: Record "Purch. Rcpt. Header";
+  begin
+    _PurchRcptHeader.SetLoadFields("No.");
+    exit(_PurchRcptHeader.Get(pReceiptNo));
+  end;
+
+  local procedure FormatNotification(pReceiptNo: Code[20]) rMessage: Text
+  var
+    _ReceiptPostedLbl: Label 'Receipt %1 has been posted.', Comment = '%1 = Receipt No.';
+  begin
+    rMessage := StrSubstNo(_ReceiptPostedLbl, pReceiptNo);
+  end;
+}
