@@ -0,0 +1,18 @@
+codeunit 50119 "Payment Terms Sync ARG"
+{
+  Access = Internal;
+
+  procedure UpdatePaymentTermsNote(pCode: Code[10]; pNote: Text[100]) rUpdated: Boolean
+  var
+    _PaymentTerms: Record "Payment Terms";
+  begin
+    _PaymentTerms.SetLoadFields(Description);
+    if not _PaymentTerms.Get(pCode) then
+      exit(false);
+    if _PaymentTerms.Description <> pNote then begin
+      _PaymentTerms.Description := pNote;
+      _PaymentTerms.Modify();
+      rUpdated := true;
+    end;
+  end;
+}
